class IPAddress:
    MAX_OCTET_VALUE = 255
    MIN_OCTET_VALUE = 0
    OCTET_COUNT = 4
    BINARY_FORMAT = '08b'
    SEPARATOR = '.'

    def __init__(self, ip_address):
        self._ip_address = ip_address

    @property
    def ip_address(self):
        return self._ip_address

    @ip_address.setter
    def ip_address(self, value):
        self._ip_address = value

    def is_valid(self):
        return self._has_four_octets() and self._all_octets_in_range()

    def _has_four_octets(self):
        return len(self._get_octets_raw()) == self.OCTET_COUNT

    def _all_octets_in_range(self):
        return all(self._is_valid_octet(octet) for octet in self._get_octets_raw())

    def _is_valid_octet(self, octet):
        return octet.isdigit() and self.MIN_OCTET_VALUE <= int(octet) <= self.MAX_OCTET_VALUE

    def _get_octets_raw(self):
        return self._ip_address.split(self.SEPARATOR)

    def get_octets(self):
        if self.is_valid():
            return self._get_octets_raw()
        return []

    def get_binary(self):
        if not self.is_valid():
            return ''
        return self.SEPARATOR.join(self._octets_to_binary())

    def _octets_to_binary(self):
        return [format(int(octet), self.BINARY_FORMAT) for octet in self.get_octets()]
